HttpSession s = request.getSession(false);          // validate, do not create
if (s == null || s.isNew()) { response.sendRedirect("/login"); return; }
Object user = s.getAttribute("user");
request.changeSessionId();                          // regenerate after login / role change
s.invalidate();                                     // logout: record is gone

